<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { administrationApi, ApiError, type RoleDefinition } from '../services/api'
import { useAuthStore } from '../stores/auth'
const auth = useAuthStore(); const items = ref<RoleDefinition[]>([]); const name = ref(''); const description = ref(''); const error = ref(''); const success = ref(''); const form = ref()
async function load() { try { items.value = await administrationApi.listRoles(auth.token) } catch (e) { error.value = e instanceof ApiError ? e.message : 'No fue posible cargar los roles.' } }
async function save() { const validation = await form.value.validate(); if (!validation.valid) return; error.value=''; success.value=''; try { await administrationApi.createRole({ name: name.value, description: description.value || undefined }, auth.token); name.value=''; description.value=''; success.value='Rol creado correctamente.'; await load() } catch (e) { error.value = e instanceof ApiError ? e.message : 'No fue posible crear el rol.' } }
async function changeStatus(item: RoleDefinition, status: boolean) { error.value=''; try { const updated=await administrationApi.updateRoleStatus(item.id,status,auth.token); items.value=items.value.map(x=>x.id===updated.id?updated:x) } catch(e) { error.value=e instanceof ApiError?e.message:'No fue posible actualizar el rol.' } }
onMounted(load)
</script>
<template><v-app><v-app-bar color="primary"><v-app-bar-title><v-icon>mdi-shield-account</v-icon> Roles del sistema</v-app-bar-title><v-btn to="/panel" prepend-icon="mdi-view-dashboard">Panel</v-btn></v-app-bar><v-main><v-container class="py-8"><v-row><v-col cols="12" md="4"><v-card><v-card-title>Crear rol</v-card-title><v-card-text><v-form ref="form" @submit.prevent="save"><v-text-field v-model="name" label="Nombre del rol" hint="Debe ser único" :rules="[v=>!!v||'El nombre es obligatorio',v=>v?.trim().length>=3||'Mínimo 3 caracteres']"/><v-textarea v-model="description" label="Descripción" rows="3"/><v-btn color="primary" type="submit" block>Crear rol</v-btn></v-form></v-card-text></v-card></v-col><v-col cols="12" md="8"><v-card><v-card-title>Administrar roles</v-card-title><v-card-text><v-alert v-if="error" type="error" class="mb-3">{{error}}</v-alert><v-alert v-if="success" type="success" class="mb-3">{{success}}</v-alert><v-table><thead><tr><th>Rol</th><th>Descripción</th><th>Estado</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{item.name}}</td><td>{{item.description || '—'}}</td><td><v-switch :model-value="item.status" color="primary" :label="item.status?'Activo':'Inactivo'" hide-details @update:model-value="changeStatus(item, Boolean($event))"/></td></tr><tr v-if="!items.length"><td colspan="3" class="text-center py-5">No hay roles registrados.</td></tr></tbody></v-table></v-card-text></v-card></v-col></v-row></v-container></v-main></v-app></template>
